  @override
  String get legalDataConsentRetentionBody =>
      'ਅਗਿਆਤ ਸਿਖਲਾਈ ਡੇਟਾਸੈਟਾਂ ਨੂੰ ਮਾਡਲ ਵਿਕਾਸ ਲਈ ਲੋੜੀਂਦੀ ਮਿਆਦ ਲਈ ਬਰਕਰਾਰ ਰੱਖਿਆ ਜਾਂਦਾ ਹੈ, ਖਾਸ ਤੌਰ \'ਤੇ ਸਿਰਜਣ ਤੋਂ 24 ਮਹੀਨੇ। ਫਾਈਨ-ਟਿਊਨਿੰਗ ਡੇਟਾਸੈਟਾਂ ਲਈ 12 ਮਹੀਨਿਆਂ ਬਾਅਦ ਸਪੱਸ਼ਟ ਤੌਰ \'ਤੇ ਮੁੜ-ਸਹਿਮਤੀ ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ। ਕਿਰਾਏਦਾਰ ਦੇ ਖਾਤੇ ਦੇ ਬੰਦ ਹੋਣ \'ਤੇ, ਉਸ ਕਿਰਾਏਦਾਰ ਦੀ ਸਮੱਗਰੀ ਤੋਂ ਲਿਆ ਗਿਆ ਸਾਰਾ ਸਿਖਲਾਈ ਡੇਟਾ 60 ਦਿਨਾਂ ਦੇ ਅੰਦਰ ਸਾਫ਼ ਕਰ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ।';

