  @override
  String get legalDisclaimerNoPrivilegeBody =>
      'Umbrella\'s AI ਨਾਲ ਸੰਚਾਰ ਕਿਸੇ ਵੀ ਅਧਿਕਾਰ ਖੇਤਰ ਵਿੱਚ ਅਟਾਰਨੀ-ਕਲਾਇੰਟ ਵਿਸ਼ੇਸ਼ ਅਧਿਕਾਰ ਜਾਂ ਕਾਨੂੰਨੀ ਪੇਸ਼ੇਵਰ ਵਿਸ਼ੇਸ਼ ਅਧਿਕਾਰ ਦੁਆਰਾ ਸੁਰੱਖਿਅਤ ਨਹੀਂ ਹਨ। ਉਸ ਪਲੇਟਫਾਰਮ \'ਤੇ ਜਾਣਕਾਰੀ ਜਮ੍ਹਾਂ ਨਾ ਕਰੋ ਜਿਸ ਨੂੰ ਤੁਸੀਂ ਵਿਸ਼ੇਸ਼ ਅਧਿਕਾਰ ਦੇ ਤਹਿਤ ਸੁਰੱਖਿਅਤ ਕਰਨਾ ਚਾਹੁੰਦੇ ਹੋ। ਜੇਕਰ ਤੁਸੀਂ ਅੰਬਰੇਲਾ ਮਾਰਕਿਟਪਲੇਸ ਰਾਹੀਂ ਕਿਸੇ ਲਾਇਸੰਸਸ਼ੁਦਾ ਵਕੀਲ ਨੂੰ ਸ਼ਾਮਲ ਕਰਦੇ ਹੋ, ਤਾਂ ਵਿਸ਼ੇਸ਼ ਅਧਿਕਾਰ ਉਸ ਵਕੀਲ ਨਾਲ ਤੁਹਾਡੇ ਸੰਚਾਰਾਂ ਨਾਲ ਇੱਕ ਐਗਜ਼ੀਕਿਊਟਿਡ ਰਿਟੇਨਰ ਇਕਰਾਰਨਾਮੇ ਦੇ ਤਹਿਤ ਜੁੜ ਸਕਦਾ ਹੈ, ਪਰ ਤੁਹਾਡੇ ਪੁਰਾਣੇ AI ਇੰਟਰੈਕਸ਼ਨਾਂ ਨਾਲ ਨਹੀਂ।';

