  @override
  String get legalDisclaimerRegulatoryBody =>
      'DVTech Ventures ਇੱਕ ਤਕਨਾਲੋਜੀ ਕੰਪਨੀ ਹੈ, ਇੱਕ ਨਿਯੰਤ੍ਰਿਤ ਕਾਨੂੰਨੀ ਸੇਵਾਵਾਂ ਪ੍ਰਦਾਤਾ ਨਹੀਂ ਹੈ। ਅਸੀਂ ਕਾਨੂੰਨੀ ਸੇਵਾਵਾਂ ਪ੍ਰਦਾਨ ਕਰਨ ਲਈ ਸਾਲੀਸਿਟਰਜ਼ ਰੈਗੂਲੇਸ਼ਨ ਅਥਾਰਟੀ (ਯੂ.ਕੇ.), ਬਾਰ ਕੌਂਸਲ ਆਫ਼ ਇੰਡੀਆ, ਲਾਅ ਸੋਸਾਇਟੀ ਆਫ਼ ਕੀਨੀਆ, ਕਿਸੇ ਵੀ ਅਮਰੀਕੀ ਰਾਜ ਬਾਰ, ਜਾਂ ਕਿਸੇ ਹੋਰ ਕਾਨੂੰਨੀ ਰੈਗੂਲੇਟਰੀ ਸੰਸਥਾ ਦੁਆਰਾ ਅਧਿਕਾਰਤ ਨਹੀਂ ਹਾਂ। ਅੰਬਰੇਲਾ ਪਲੇਟਫਾਰਮ ਲੀਗਲ ਸਰਵਿਸਿਜ਼ ਐਕਟ 2007 (ਯੂ.ਕੇ.) ਵਿੱਚ ਪਰਿਭਾਸ਼ਿਤ ਕੀਤੇ ਅਨੁਸਾਰ ਨਿਯੰਤ੍ਰਿਤ ਕਾਨੂੰਨੀ ਗਤੀਵਿਧੀ ਪ੍ਰਦਾਨ ਨਹੀਂ ਕਰਦਾ ਹੈ ਜਾਂ ਹੋਰ ਅਧਿਕਾਰ ਖੇਤਰਾਂ ਵਿੱਚ ਬਰਾਬਰ ਕਾਨੂੰਨ ਪ੍ਰਦਾਨ ਕਰਦਾ ਹੈ।';

