  @override
  String get legalDisclaimerScopeBody =>
      'ਇਹ ਬੇਦਾਅਵਾ ਅੰਬਰੇਲਾ ਪਲੇਟਫਾਰਮ ਦੀ ਹਰੇਕ ਵਿਸ਼ੇਸ਼ਤਾ \'ਤੇ ਲਾਗੂ ਹੁੰਦਾ ਹੈ, ਜਿਸ ਵਿੱਚ ਸ਼ਾਮਲ ਹੈ ਪਰ ਇਹਨਾਂ ਤੱਕ ਸੀਮਿਤ ਨਹੀਂ: ਕਾਨੂੰਨੀ ਮੁੱਦਾ ਜਾਂਚਕਰਤਾ, AI ਕੋਪਾਇਲਟ, ਦਸਤਾਵੇਜ਼ ਸਮੀਖਿਆ, ਕਾਨੂੰਨੀ ਖੋਜ, ਮਾਮਲੇ ਦਾ ਵਿਸ਼ਲੇਸ਼ਣ, ਰਣਨੀਤੀ ਮੀਮੋ, ਡਰਾਫਟ ਦਸਤਾਵੇਜ਼, ਅਤੇ ਕੋਈ ਵੀ ਹੋਰ AI ਦੁਆਰਾ ਤਿਆਰ ਕੀਤੀ ਸਮੱਗਰੀ। ਇਹ ਸਾਰੇ ਉਪਭੋਗਤਾਵਾਂ - ਉਪਭੋਗਤਾਵਾਂ, ਵਕੀਲ ਉਪਭੋਗਤਾਵਾਂ, ਅਤੇ ਕਨੂੰਨੀ ਫਰਮ ਦੇ ਕਿਰਾਏਦਾਰਾਂ - ਉਹਨਾਂ ਸਾਰੇ ਅਧਿਕਾਰ ਖੇਤਰਾਂ ਵਿੱਚ ਲਾਗੂ ਹੁੰਦਾ ਹੈ ਜਿਸ ਵਿੱਚ Umbrella ਕੰਮ ਕਰਦਾ ਹੈ (ਭਾਰਤ, ਸੰਯੁਕਤ ਰਾਜ, ਕੀਨੀਆ, ਅਤੇ ਯੂਨਾਈਟਿਡ ਕਿੰਗਡਮ)।';

