  @override
  String get legalPrivacyAutomatedBody =>
      'ਛਤਰੀ ਕਾਨੂੰਨੀ ਵਿਸ਼ਲੇਸ਼ਣ ਤਿਆਰ ਕਰਨ, ਮੁੱਦਿਆਂ ਦੀ ਪਛਾਣ ਕਰਨ ਅਤੇ ਕਾਰਵਾਈਆਂ ਦਾ ਸੁਝਾਅ ਦੇਣ ਲਈ AI ਦੀ ਵਰਤੋਂ ਕਰਦੀ ਹੈ। ਇਹ AI ਆਉਟਪੁੱਟ ਸਿਰਫ ਜਾਣਕਾਰੀ ਵਾਲੇ ਹਨ ਅਤੇ ਤੁਹਾਡੇ ਕਨੂੰਨੀ ਅਧਿਕਾਰਾਂ ਬਾਰੇ ਬਾਈਡਿੰਗ ਫੈਸਲਿਆਂ ਦਾ ਗਠਨ ਨਹੀਂ ਕਰਦੇ ਹਨ। ਮਨੁੱਖੀ ਸਮੀਖਿਆ ਤੋਂ ਬਿਨਾਂ ਤੁਹਾਡੇ ਬਾਰੇ ਕਾਨੂੰਨੀ ਜਾਂ ਇਸੇ ਤਰ੍ਹਾਂ ਦੇ ਮਹੱਤਵਪੂਰਨ ਪ੍ਰਭਾਵ ਵਾਲਾ ਕੋਈ ਵੀ ਪੂਰੀ ਤਰ੍ਹਾਂ ਸਵੈਚਲਿਤ ਫੈਸਲਾ ਨਹੀਂ ਲਿਆ ਜਾਂਦਾ ਹੈ। ਧੋਖਾਧੜੀ ਦਾ ਪਤਾ ਲਗਾਉਣ ਲਈ ਸਾਡੀ AI ਜੋਖਮ-ਸਕੋਰਿੰਗ ਪਲੇਟਫਾਰਮ ਪਹੁੰਚ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕਰ ਸਕਦੀ ਹੈ; ਤੁਸੀਂ ਅਜਿਹੇ ਕਿਸੇ ਵੀ ਫੈਸਲੇ ਦੀ ਮਨੁੱਖੀ ਸਮੀਖਿਆ ਦੀ ਬੇਨਤੀ ਕਰ ਸਕਦੇ ਹੋ।';

