  @override
  String get legalPrivacyChangesBody =>
      'ਅਸੀਂ ਸਮੇਂ-ਸਮੇਂ \'ਤੇ ਇਸ ਗੋਪਨੀਯਤਾ ਨੀਤੀ ਨੂੰ ਅਪਡੇਟ ਕਰ ਸਕਦੇ ਹਾਂ। ਸਮੱਗਰੀ ਤਬਦੀਲੀਆਂ ਨੂੰ ਲਾਗੂ ਹੋਣ ਤੋਂ ਘੱਟੋ-ਘੱਟ 30 ਦਿਨ ਪਹਿਲਾਂ ਈਮੇਲ ਅਤੇ ਇਨ-ਐਪ ਸੂਚਨਾ ਦੁਆਰਾ ਸੂਚਿਤ ਕੀਤਾ ਜਾਵੇਗਾ। ਪ੍ਰਭਾਵੀ ਮਿਤੀ ਤੋਂ ਬਾਅਦ ਪਲੇਟਫਾਰਮ ਦੀ ਨਿਰੰਤਰ ਵਰਤੋਂ ਅਪਡੇਟ ਕੀਤੀ ਨੀਤੀ ਨੂੰ ਸਵੀਕਾਰ ਕਰਦੀ ਹੈ।';

