  String get legalPrivacyChangesHeading => '13. ਇਸ ਨੀਤੀ ਵਿੱਚ ਬਦਲਾਅ';

  @override
  String get legalPrivacyChildrenBody =>
      'ਛਤਰੀ 18 ਸਾਲ ਤੋਂ ਘੱਟ ਉਮਰ ਦੇ ਵਿਅਕਤੀਆਂ \'ਤੇ ਨਿਰਦੇਸ਼ਿਤ ਨਹੀਂ ਹੈ। ਅਸੀਂ ਜਾਣਬੁੱਝ ਕੇ ਬੱਚਿਆਂ ਤੋਂ ਨਿੱਜੀ ਡਾਟਾ ਇਕੱਠਾ ਨਹੀਂ ਕਰਦੇ ਹਾਂ। ਜੇਕਰ ਤੁਹਾਨੂੰ ਲੱਗਦਾ ਹੈ ਕਿ ਕਿਸੇ ਬੱਚੇ ਨੇ ਸਾਡੇ ਕੋਲ ਡਾਟਾ ਜਮ੍ਹਾ ਕੀਤਾ ਹੈ, ਤਾਂ support@odaflow.com \'ਤੇ ਸੰਪਰਕ ਕਰੋ ਅਤੇ ਅਸੀਂ ਇਸਨੂੰ ਤੁਰੰਤ ਮਿਟਾ ਦੇਵਾਂਗੇ।';

  @override
  String get legalPrivacyChildrenHeading => '8. ਬੱਚੇ';

  @override
