      'ਖਾਤਾ ਡੇਟਾ: ਈਮੇਲ ਪਤਾ, ਪੂਰਾ ਨਾਮ, ਫ਼ੋਨ ਨੰਬਰ (ਵਿਕਲਪਿਕ), ਰਿਹਾਇਸ਼ ਦਾ ਦੇਸ਼, ਅਤੇ ਪਾਸਵਰਡ ਹੈਸ਼। ਵਕੀਲ ਉਪਭੋਗਤਾਵਾਂ ਲਈ: ਬਾਰ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਨੰਬਰ, ਫਰਮ ਦਾ ਨਾਮ, ਅਭਿਆਸ ਖੇਤਰ, ਅਤੇ ਅਧਿਕਾਰ ਖੇਤਰ।';

  @override
  String get legalPrivacyCollectBillingBody =>
      'ਬਿਲਿੰਗ ਡੇਟਾ: ਗਾਹਕੀ ਯੋਜਨਾ, ਭੁਗਤਾਨ ਵਿਧੀ ਦੀ ਕਿਸਮ (ਕਾਰਡ ਬ੍ਰਾਂਡ, ਆਖਰੀ ਚਾਰ ਅੰਕ), ਬਿਲਿੰਗ ਪਤਾ, ਅਤੇ ਲੈਣ-ਦੇਣ ਦਾ ਇਤਿਹਾਸ। ਪੂਰੇ ਭੁਗਤਾਨ ਕਾਰਡ ਦੇ ਵੇਰਵਿਆਂ ਨੂੰ ਸਾਡੇ PCI-DSS-ਅਨੁਕੂਲ ਭੁਗਤਾਨ ਪ੍ਰੋਸੈਸਰ (ਸਟਰਾਈਪ) ਦੁਆਰਾ ਸੰਭਾਲਿਆ ਜਾਂਦਾ ਹੈ ਅਤੇ ਕਦੇ ਵੀ ਸਾਡੇ ਸਰਵਰਾਂ \'ਤੇ ਸਟੋਰ ਨਹੀਂ ਕੀਤਾ ਜਾਂਦਾ ਹੈ।';

  @override
  String get legalPrivacyCollectContentBody =>
