      'ਕੂਕੀਜ਼ ਅਤੇ ਟਰੈਕਿੰਗ: ਅਸੀਂ ਸਖਤੀ ਨਾਲ-ਜ਼ਰੂਰੀ ਸੈਸ਼ਨ ਕੂਕੀਜ਼, ਕਾਰਜਾਤਮਕ ਤਰਜੀਹ ਕੂਕੀਜ਼, ਅਤੇ — ਤੁਹਾਡੀ ਸਹਿਮਤੀ ਨਾਲ — ਵਿਸ਼ਲੇਸ਼ਣ ਕੁਕੀਜ਼ (ਵਰਸੇਲ ਵਿਸ਼ਲੇਸ਼ਣ, ਸੰਤਰੀ ਗਲਤੀ ਟਰੈਕਿੰਗ) ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਹਾਂ। ਤੁਸੀਂ ਕੂਕੀ ਸੈਟਿੰਗਾਂ ਪੈਨਲ ਰਾਹੀਂ ਕੂਕੀ ਤਰਜੀਹਾਂ ਦਾ ਪ੍ਰਬੰਧਨ ਕਰ ਸਕਦੇ ਹੋ।';

