  @override
  String get legalPrivacyCollectUsageBody =>
      'ਵਰਤੋਂ ਡੇਟਾ: ਵਿਜ਼ਿਟ ਕੀਤੇ ਗਏ ਪੰਨੇ, ਵਰਤੀਆਂ ਗਈਆਂ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ, ਸਪੁਰਦ ਕੀਤੇ AI ਸਵਾਲ, ਅਪਲੋਡ ਕੀਤੇ ਗਏ ਦਸਤਾਵੇਜ਼, ਸਮਾਂ ਬਿਤਾਇਆ, ਇਵੈਂਟਾਂ \'ਤੇ ਕਲਿੱਕ ਕਰੋ, ਅਤੇ ਸੈਸ਼ਨ ਰਿਕਾਰਡਿੰਗਾਂ (ਜਿੱਥੇ ਸਹਿਮਤੀ ਦਿੱਤੀ ਜਾਂਦੀ ਹੈ)। ਇਹ ਡੇਟਾ ਪਹਿਲੀ-ਪਾਰਟੀ ਵਿਸ਼ਲੇਸ਼ਣ ਦੁਆਰਾ ਇਕੱਤਰ ਕੀਤਾ ਜਾਂਦਾ ਹੈ।';

  @override
  String get legalPrivacyContactBody =>
      'ਡਾਟਾ ਸੁਰੱਖਿਆ ਪੁੱਛਗਿੱਛ: support@odaflow.com. ਅਸੀਂ 10 ਕਾਰੋਬਾਰੀ ਦਿਨਾਂ ਦੇ ਅੰਦਰ ਜਵਾਬ ਦੇਣ ਦਾ ਟੀਚਾ ਰੱਖਦੇ ਹਾਂ। ਜੇਕਰ ਤੁਸੀਂ ਸਾਡੇ ਜਵਾਬ ਤੋਂ ਅਸੰਤੁਸ਼ਟ ਹੋ ਤਾਂ ਤੁਹਾਨੂੰ ਆਪਣੀ ਸਥਾਨਕ ਡਾਟਾ ਸੁਰੱਖਿਆ ਅਥਾਰਟੀ ਕੋਲ ਸ਼ਿਕਾਇਤ ਦਰਜ ਕਰਨ ਦਾ ਅਧਿਕਾਰ ਹੈ: UK — ICO (ico.org.uk); EU — ਤੁਹਾਡਾ ਰਾਸ਼ਟਰੀ DPA; ਭਾਰਤ - ਡਾਟਾ ਪ੍ਰੋਟੈਕਸ਼ਨ ਬੋਰਡ ਆਫ਼ ਇੰਡੀਆ; ਕੀਨੀਆ — ਡਾਟਾ ਪ੍ਰੋਟੈਕਸ਼ਨ ਕਮਿਸ਼ਨਰ ਦਾ ਦਫ਼ਤਰ (odpc.go.ke)।';

  @override
  String get legalPrivacyContactHeading => '14. ਸਾਡੇ ਨਾਲ ਸੰਪਰਕ ਕਰੋ';

  @override
  String get legalPrivacyControllerBody =>
      'ਛਤਰੀ DVTech ਵੈਂਚਰਸ (\"ਅਸੀਂ\", \"ਸਾਨੂੰ\", \"ਸਾਡੇ\") ਦੁਆਰਾ ਚਲਾਈ ਜਾਂਦੀ ਹੈ। ਅਸੀਂ ਖਪਤਕਾਰਾਂ ਤੋਂ ਇਕੱਤਰ ਕੀਤੀ ਜਾਣਕਾਰੀ ਲਈ ਡੇਟਾ ਕੰਟਰੋਲਰ ਦੇ ਤੌਰ \'ਤੇ ਅਤੇ ਲਾਅ ਫਰਮ ਕਿਰਾਏਦਾਰਾਂ ਦੀ ਤਰਫੋਂ ਰੱਖੀ ਗਈ ਜਾਣਕਾਰੀ ਲਈ ਡੇਟਾ ਪ੍ਰੋਸੈਸਰ ਵਜੋਂ ਕੰਮ ਕਰਦੇ ਹਾਂ। ਰਜਿਸਟਰਡ ਪਤਾ ਅਤੇ ਡਾਟਾ-ਸੁਰੱਖਿਆ ਸੰਪਰਕ: support@odaflow.com। GDPR ਉਦੇਸ਼ਾਂ ਲਈ, ਸਾਡੇ EU/UK ਪ੍ਰਤੀਨਿਧੀ ਨੂੰ ਉਸੇ ਪਤੇ \'ਤੇ ਸੰਪਰਕ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ।';

  @override
  String get legalPrivacyControllerHeading => '1. ਅਸੀਂ ਕੌਣ ਹਾਂ';

  @override
  String get legalPrivacyCookiesBody =>
      'ਸਖਤੀ ਨਾਲ ਲੋੜੀਂਦੀਆਂ ਕੂਕੀਜ਼ (ਸੈਸ਼ਨ ਪ੍ਰਬੰਧਨ, ਸੁਰੱਖਿਆ ਟੋਕਨ) ਹਮੇਸ਼ਾ ਕਿਰਿਆਸ਼ੀਲ ਹੁੰਦੀਆਂ ਹਨ। ਫੰਕਸ਼ਨਲ ਕੂਕੀਜ਼ (ਭਾਸ਼ਾ ਤਰਜੀਹ, ਥੀਮ) ਪਹਿਲੀ ਵਰਤੋਂ \'ਤੇ ਸੈੱਟ ਹਨ ਅਤੇ ਬ੍ਰਾਊਜ਼ਰ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਸਾਫ਼ ਕੀਤੀਆਂ ਜਾ ਸਕਦੀਆਂ ਹਨ। ਵਿਸ਼ਲੇਸ਼ਣ ਕੂਕੀਜ਼ (Vercel, Sentry) ਸਿਰਫ਼ ਕੂਕੀ ਬੈਨਰ ਰਾਹੀਂ ਤੁਹਾਡੀ ਸਹਿਮਤੀ ਨਾਲ ਸੈੱਟ ਕੀਤੀਆਂ ਜਾਂਦੀਆਂ ਹਨ। ਅਸੀਂ ਇਸ਼ਤਿਹਾਰਬਾਜ਼ੀ ਜਾਂ ਕਰਾਸ-ਸਾਈਟ ਟਰੈਕਿੰਗ ਕੂਕੀਜ਼ ਦੀ ਵਰਤੋਂ ਨਹੀਂ ਕਰਦੇ ਹਾਂ।';

  @override
  String get legalPrivacyCookiesHeading => '12. ਕੂਕੀਜ਼';

  @override
  String get legalPrivacyDescription =>
      'ਅੰਬਰੇਲਾ ਤੁਹਾਡੀ ਜਾਣਕਾਰੀ ਨੂੰ ਕਿਵੇਂ ਇਕੱਠਾ ਕਰਦੀ ਹੈ, ਵਰਤਦੀ ਹੈ ਅਤੇ ਸੁਰੱਖਿਅਤ ਕਰਦੀ ਹੈ। ਇਹ ਨੀਤੀ ਭਾਰਤ, ਸੰਯੁਕਤ ਰਾਜ, ਕੀਨੀਆ, ਅਤੇ ਯੂਨਾਈਟਿਡ ਕਿੰਗਡਮ ਵਿੱਚ umbrella.okaylegal.ai ਦੇ ਸਾਰੇ ਉਪਭੋਗਤਾਵਾਂ ਅਤੇ ਸੰਬੰਧਿਤ ਛਤਰੀ ਐਪਲੀਕੇਸ਼ਨਾਂ \'ਤੇ ਲਾਗੂ ਹੁੰਦੀ ਹੈ।';

  @override
  String get legalPrivacyLegalBasisBody =>
      'ਅਸੀਂ ਤੁਹਾਡੇ ਅਧਿਕਾਰ ਖੇਤਰ \'ਤੇ ਨਿਰਭਰ ਕਰਦੇ ਹੋਏ ਨਿਮਨਲਿਖਤ ਕਨੂੰਨੀ ਅਧਾਰਾਂ ਦੇ ਅਧੀਨ ਨਿੱਜੀ ਡੇਟਾ ਦੀ ਪ੍ਰਕਿਰਿਆ ਕਰਦੇ ਹਾਂ: (ਏ) ਇਕਰਾਰਨਾਮਾ — ਤੁਹਾਡੇ ਦੁਆਰਾ ਸਾਈਨ ਅੱਪ ਕੀਤੀਆਂ ਸੇਵਾਵਾਂ ਪ੍ਰਦਾਨ ਕਰਨ ਲਈ ਲੋੜੀਂਦੀ ਪ੍ਰਕਿਰਿਆ; (ਬੀ) ਜਾਇਜ਼ ਹਿੱਤ — ਧੋਖਾਧੜੀ ਦੀ ਰੋਕਥਾਮ, ਪਲੇਟਫਾਰਮ ਸੁਰੱਖਿਆ, ਉਤਪਾਦ ਸੁਧਾਰ; (c) ਸਹਿਮਤੀ — AI ਸਿਖਲਾਈ, ਮਾਰਕੀਟਿੰਗ ਈਮੇਲ, ਸਖਤੀ ਨਾਲ ਲੋੜ ਤੋਂ ਵੱਧ ਕੂਕੀਜ਼; (d) ਕਾਨੂੰਨੀ ਜ਼ਿੰਮੇਵਾਰੀ — ਲਾਗੂ ਕਾਨੂੰਨ ਦੀ ਪਾਲਣਾ। ਭਾਰਤ ਲਈ, ਪ੍ਰੋਸੈਸਿੰਗ ਨੂੰ ਡਿਜੀਟਲ ਪਰਸਨਲ ਡੇਟਾ ਪ੍ਰੋਟੈਕਸ਼ਨ ਐਕਟ 2023 (DPDP ਐਕਟ) ਦੁਆਰਾ ਨਿਯੰਤਰਿਤ ਕੀਤਾ ਜਾਂਦਾ ਹੈ। UK/EU ਲਈ, ਪ੍ਰੋਸੈਸਿੰਗ UK GDPR ਅਤੇ EU GDPR ਦੀ ਪਾਲਣਾ ਕਰਦੀ ਹੈ। ਕੀਨੀਆ ਲਈ, ਪ੍ਰੋਸੈਸਿੰਗ ਡੇਟਾ ਪ੍ਰੋਟੈਕਸ਼ਨ ਐਕਟ 2019 ਦੀ ਪਾਲਣਾ ਕਰਦੀ ਹੈ। ਯੂਐਸ ਉਪਭੋਗਤਾਵਾਂ ਲਈ, ਅਸੀਂ CCPA/CPRA ਸਮੇਤ ਲਾਗੂ ਰਾਜ ਦੇ ਪਰਦੇਦਾਰੀ ਕਾਨੂੰਨਾਂ ਦੀ ਪਾਲਣਾ ਕਰਦੇ ਹਾਂ।';

  @override
  String get legalPrivacyLegalBasisHeading => '2. ਪ੍ਰੋਸੈਸਿੰਗ ਲਈ ਕਾਨੂੰਨੀ ਅਧਾਰ';

  @override
  String get legalPrivacyPolicy => 'ਪਰਾਈਵੇਟ ਨੀਤੀ';

  @override
  String get legalPrivacyRetentionBody =>
      'ਜਦੋਂ ਤੱਕ ਤੁਹਾਡਾ ਖਾਤਾ ਕਿਰਿਆਸ਼ੀਲ ਹੈ ਅਸੀਂ ਨਿੱਜੀ ਡੇਟਾ ਨੂੰ ਬਰਕਰਾਰ ਰੱਖਦੇ ਹਾਂ। ਖਾਤਾ ਮਿਟਾਉਣ \'ਤੇ, ਅਸੀਂ 30 ਦਿਨਾਂ ਦੇ ਅੰਦਰ ਨਿੱਜੀ ਡੇਟਾ ਨੂੰ ਮਿਟਾ ਦਿੰਦੇ ਹਾਂ ਜਾਂ ਅਗਿਆਤ ਕਰ ਦਿੰਦੇ ਹਾਂ, ਸਿਵਾਏ ਜਿੱਥੇ ਕਨੂੰਨ ਦੁਆਰਾ ਧਾਰਨ ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ (ਉਦਾਹਰਣ ਵਜੋਂ, ਟੈਕਸ ਪਾਲਣਾ ਲਈ 7 ਸਾਲਾਂ ਲਈ ਰੱਖੇ ਗਏ ਬਿਲਿੰਗ ਰਿਕਾਰਡ, 12 ਮਹੀਨਿਆਂ ਲਈ ਰੱਖੇ ਗਏ ਆਡਿਟ ਲੌਗ)। ਫਰਮ ਕਿਰਾਏਦਾਰ ਗਵਰਨੈਂਸ ਸੈਟਿੰਗਾਂ ਰਾਹੀਂ 7 ਸਾਲਾਂ ਤੱਕ ਕਸਟਮ ਧਾਰਨ ਨੀਤੀਆਂ ਨੂੰ ਕੌਂਫਿਗਰ ਕਰ ਸਕਦੇ ਹਨ। ਚੁਣੀ ਗਈ ਸਮੱਗਰੀ ਤੋਂ ਲਏ ਗਏ AI-ਸਿਖਲਾਈ ਡੇਟਾਸੇਟ ਸਾਡੀ ਡੇਟਾ ਅਤੇ AI ਸਹਿਮਤੀ ਨੀਤੀ ਵਿੱਚ ਧਾਰਨ ਅਨੁਸੂਚੀ ਦੇ ਅਧੀਨ ਹਨ।';

  @override
  String get legalPrivacyRetentionHeading => '6. ਧਾਰਨ';

  @override
  String get legalPrivacyRightsCCPABody =>
      'ਕੈਲੀਫੋਰਨੀਆ (CCPA/CPRA) ਅਧਿਕਾਰ: ਇਹ ਜਾਣਨ ਦਾ ਅਧਿਕਾਰ ਕਿ ਅਸੀਂ ਕਿਹੜੀ ਨਿੱਜੀ ਜਾਣਕਾਰੀ ਇਕੱਠੀ ਕਰਦੇ ਹਾਂ; ਮਿਟਾਉਣ ਦਾ ਅਧਿਕਾਰ; ਵਿਕਰੀ ਤੋਂ ਬਾਹਰ ਨਿਕਲਣ ਦਾ ਅਧਿਕਾਰ (ਅਸੀਂ ਡੇਟਾ ਨਹੀਂ ਵੇਚਦੇ); ਅਧਿਕਾਰਾਂ ਦੀ ਵਰਤੋਂ ਕਰਨ ਲਈ ਗੈਰ-ਵਿਤਕਰੇ ਦਾ ਅਧਿਕਾਰ; ਗਲਤ ਜਾਣਕਾਰੀ ਨੂੰ ਠੀਕ ਕਰਨ ਦਾ ਅਧਿਕਾਰ; ਸੰਵੇਦਨਸ਼ੀਲ ਨਿੱਜੀ ਜਾਣਕਾਰੀ ਦੀ ਵਰਤੋਂ ਨੂੰ ਸੀਮਤ ਕਰਨ ਦਾ ਅਧਿਕਾਰ।';

  @override
  String get legalPrivacyRightsDPDPBody =>
      'ਇੰਡੀਆ DPDP ਐਕਟ ਅਧਿਕਾਰ: ਤੁਹਾਡੇ ਡਿਜੀਟਲ ਨਿੱਜੀ ਡੇਟਾ ਤੱਕ ਪਹੁੰਚ, ਸੁਧਾਰ ਅਤੇ ਮਿਟਾਉਣ ਦਾ ਅਧਿਕਾਰ; ਸ਼ਿਕਾਇਤ ਨਿਵਾਰਣ ਦਾ ਅਧਿਕਾਰ; ਤੁਹਾਡੀ ਤਰਫੋਂ ਅਧਿਕਾਰਾਂ ਦੀ ਵਰਤੋਂ ਕਰਨ ਲਈ ਕਿਸੇ ਵਿਅਕਤੀ ਨੂੰ ਨਾਮਜ਼ਦ ਕਰਨ ਦਾ ਅਧਿਕਾਰ। support@odaflow.com \'ਤੇ ਸਾਡੇ ਸਹਿਮਤੀ ਪ੍ਰਬੰਧਕ ਨਾਲ ਸੰਪਰਕ ਕਰੋ।';

  @override
  String get legalPrivacyRightsGDPRBody =>
      'GDPR / UK GDPR ਅਧਿਕਾਰ (EU ਅਤੇ UK ਉਪਭੋਗਤਾ): ਪਹੁੰਚ — ਆਪਣੇ ਨਿੱਜੀ ਡੇਟਾ ਦੀ ਇੱਕ ਕਾਪੀ ਪ੍ਰਾਪਤ ਕਰੋ; ਸੁਧਾਰ - ਸਹੀ ਗਲਤ ਡੇਟਾ; ਮਿਟਾਉਣ ਦੀ ਬੇਨਤੀ (ਕਾਨੂੰਨੀ ਰੋਕ ਦੇ ਅਧੀਨ); ਪਾਬੰਦੀ - ਜਦੋਂ ਇੱਕ ਵਿਵਾਦ ਹੱਲ ਹੋ ਜਾਂਦਾ ਹੈ ਤਾਂ ਪ੍ਰਕਿਰਿਆ ਨੂੰ ਸੀਮਤ ਕਰੋ; ਪੋਰਟੇਬਿਲਟੀ — ਮਸ਼ੀਨ ਦੁਆਰਾ ਪੜ੍ਹਨਯੋਗ ਫਾਰਮੈਟ ਵਿੱਚ ਆਪਣਾ ਡੇਟਾ ਪ੍ਰਾਪਤ ਕਰੋ; ਇਤਰਾਜ਼ - ਜਾਇਜ਼ ਹਿੱਤਾਂ ਦੇ ਆਧਾਰ \'ਤੇ ਕਾਰਵਾਈ ਕਰਨ \'ਤੇ ਇਤਰਾਜ਼; ਸਵੈਚਲਿਤ ਫੈਸਲੇ — ਮਹੱਤਵਪੂਰਨ ਪ੍ਰਭਾਵਾਂ ਵਾਲੇ ਸਿਰਫ਼ ਸਵੈਚਲਿਤ ਫ਼ੈਸਲਿਆਂ ਦੇ ਅਧੀਨ ਨਹੀਂ ਹੋਣਾ ਚਾਹੀਦਾ। ਇਹਨਾਂ ਅਧਿਕਾਰਾਂ ਦੀ ਵਰਤੋਂ ਕਰਨ ਲਈ, support@odaflow.com \'ਤੇ ਈਮੇਲ ਕਰੋ ਜਾਂ ਐਪ-ਵਿੱਚ ਗੋਪਨੀਯਤਾ ਸੈਟਿੰਗਾਂ ਦੀ ਵਰਤੋਂ ਕਰੋ।';

  @override
  String get legalPrivacyRightsHeading => '9. ਤੁਹਾਡੇ ਅਧਿਕਾਰ';

  @override
  String get legalPrivacyRightsKenyaBody =>
      'ਕੀਨੀਆ ਡੇਟਾ ਪ੍ਰੋਟੈਕਸ਼ਨ ਐਕਟ ਅਧਿਕਾਰ: ਸੂਚਿਤ ਕਰਨ ਦਾ ਅਧਿਕਾਰ; ਪਹੁੰਚ ਦਾ ਅਧਿਕਾਰ; ਸੁਧਾਰ ਕਰਨ ਦਾ ਅਧਿਕਾਰ; ਮਿਟਾਉਣ ਅਤੇ ਬਲਾਕ ਕਰਨ ਦਾ ਅਧਿਕਾਰ; ਇਤਰਾਜ਼ ਕਰਨ ਦਾ ਅਧਿਕਾਰ; ਡਾਟਾ ਪੋਰਟੇਬਿਲਟੀ ਦਾ ਅਧਿਕਾਰ। support@odaflow.com \'ਤੇ ਸਾਡੇ ਸਥਾਨਕ ਪ੍ਰਤੀਨਿਧੀ ਨਾਲ ਸੰਪਰਕ ਕਰੋ।';

  @override
  String get legalPrivacySecurityBody =>
      'ਅਸੀਂ ਤਕਨੀਕੀ ਅਤੇ ਸੰਗਠਨਾਤਮਕ ਉਪਾਵਾਂ ਨੂੰ ਲਾਗੂ ਕਰਦੇ ਹਾਂ ਜਿਸ ਵਿੱਚ ਸ਼ਾਮਲ ਹਨ: ਟ੍ਰਾਂਜਿਟ ਵਿੱਚ TLS 1.2+ ਇਨਕ੍ਰਿਪਸ਼ਨ; ਆਰਾਮ \'ਤੇ AES-256 ਇਨਕ੍ਰਿਪਸ਼ਨ; ਘੱਟ-ਅਧਿਕਾਰ ਦੇ ਸਿਧਾਂਤਾਂ ਦੇ ਨਾਲ ਭੂਮਿਕਾ-ਅਧਾਰਿਤ ਪਹੁੰਚ ਨਿਯੰਤਰਣ; ਪ੍ਰਬੰਧਕੀ ਪਹੁੰਚ ਲਈ ਬਹੁ-ਕਾਰਕ ਪ੍ਰਮਾਣਿਕਤਾ; ਸਵੈਚਲਿਤ ਕਮਜ਼ੋਰੀ ਸਕੈਨਿੰਗ; ਘੱਟੋ-ਘੱਟ ਸਾਲਾਨਾ ਪ੍ਰਵੇਸ਼ ਟੈਸਟਿੰਗ; ਅਤੇ ਇੱਕ ਘਟਨਾ ਪ੍ਰਤੀਕਿਰਿਆ ਯੋਜਨਾ। ਤੁਹਾਡੇ ਅਧਿਕਾਰਾਂ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕਰਨ ਵਾਲੇ ਨਿੱਜੀ ਡੇਟਾ ਦੀ ਉਲੰਘਣਾ ਦੀ ਸਥਿਤੀ ਵਿੱਚ, ਅਸੀਂ ਤੁਹਾਨੂੰ ਜਾਗਰੂਕ ਹੋਣ ਦੇ 72 ਘੰਟਿਆਂ ਦੇ ਅੰਦਰ ਸੂਚਿਤ ਕਰਾਂਗੇ, ਜਿਵੇਂ ਕਿ ਲਾਗੂ ਕਾਨੂੰਨ ਦੇ ਅਧੀਨ ਲੋੜੀਂਦਾ ਹੈ।';

  @override
  String get legalPrivacySecurityHeading => '7. ਸੁਰੱਖਿਆ';

  @override
  String get legalPrivacySharingBody =>
      'ਅਸੀਂ ਤੁਹਾਡਾ ਨਿੱਜੀ ਡੇਟਾ ਨਹੀਂ ਵੇਚਦੇ। ਅਸੀਂ ਸਿਰਫ ਹੇਠਾਂ ਦਿੱਤੇ ਡੇਟਾ ਨੂੰ ਸਾਂਝਾ ਕਰਦੇ ਹਾਂ:';

  @override
  String get legalPrivacySharingHeading =>
      '5. ਅਸੀਂ ਤੁਹਾਡਾ ਡੇਟਾ ਕਿਸ ਨਾਲ ਸਾਂਝਾ ਕਰਦੇ ਹਾਂ';

  @override
  String get legalPrivacySharingLawyerReview =>
      'ਵਕੀਲ ਸਮੀਖਿਆ: ਜੇਕਰ ਤੁਸੀਂ ਵਕੀਲ ਸਮੀਖਿਆ ਦੀ ਬੇਨਤੀ ਕਰਦੇ ਹੋ, ਤਾਂ ਤੁਹਾਡੇ ਕੇਸ ਦਾ ਸਾਰ (ਪੂਰੀ ਸਮਗਰੀ ਨਹੀਂ ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਇਸਨੂੰ ਅਧਿਕਾਰਤ ਨਹੀਂ ਕਰਦੇ ਹੋ) ਨੂੰ ਸਾਡੇ ਮਾਰਕੀਟਪਲੇਸ \'ਤੇ ਨਿਰਧਾਰਤ ਲਾਇਸੰਸਸ਼ੁਦਾ ਵਕੀਲ ਨਾਲ ਸਾਂਝਾ ਕੀਤਾ ਜਾਂਦਾ ਹੈ। ਤੁਸੀਂ ਕੰਟਰੋਲ ਕਰਦੇ ਹੋ ਕਿ ਕੀ ਸਾਂਝਾ ਕੀਤਾ ਜਾਂਦਾ ਹੈ।';

  @override
  String get legalPrivacySharingLegal =>
      'ਕਨੂੰਨੀ ਖੁਲਾਸੇ: ਕਨੂੰਨ, ਅਦਾਲਤੀ ਆਦੇਸ਼, ਜਾਂ ਰੈਗੂਲੇਟਰੀ ਅਥਾਰਟੀ ਦੁਆਰਾ ਲੋੜ ਪੈਣ \'ਤੇ ਅਸੀਂ ਡੇਟਾ ਦਾ ਖੁਲਾਸਾ ਕਰ ਸਕਦੇ ਹਾਂ, ਅਤੇ ਤੁਹਾਨੂੰ ਸੂਚਿਤ ਕਰਾਂਗੇ ਜਦੋਂ ਤੱਕ ਕਾਨੂੰਨੀ ਤੌਰ \'ਤੇ ਅਜਿਹਾ ਕਰਨ ਤੋਂ ਮਨਾਹੀ ਹੈ।';

  @override
  String get legalPrivacySharingSubprocessors =>
      'ਸਬਪ੍ਰੋਸੈਸਰ: ਅਸੀਂ ਡੇਟਾ-ਪ੍ਰੋਸੈਸਿੰਗ ਸਮਝੌਤਿਆਂ ਦੇ ਤਹਿਤ ਤੀਜੀ-ਧਿਰ ਦੇ ਉਪ-ਪ੍ਰੋਸੈਸਰਾਂ ਨੂੰ ਸ਼ਾਮਲ ਕਰਦੇ ਹਾਂ ਜਿਨ੍ਹਾਂ ਲਈ ਬਰਾਬਰ ਸੁਰੱਖਿਆ ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ। ਮੁੱਖ ਸ਼੍ਰੇਣੀਆਂ: (i) ਕਲਾਉਡ ਬੁਨਿਆਦੀ ਢਾਂਚਾ — AWS (ਤੁਹਾਡੇ ਦੇਸ਼ ਦੇ ਨਜ਼ਦੀਕੀ ਖੇਤਰ ਵਿੱਚ ਹੋਸਟ ਕੀਤਾ ਡੇਟਾ); (ii) ਭੁਗਤਾਨ ਦੀ ਪ੍ਰਕਿਰਿਆ - ਪੱਟੀ; (iii) ਗਲਤੀ ਨਿਗਰਾਨੀ — ਸੰਤਰੀ; (iv) ਵਿਸ਼ਲੇਸ਼ਣ — ਵਰਸੇਲ; (v) AI ਮਾਡਲ ਪ੍ਰਦਾਤਾ — OpenAI ਅਤੇ DeepSeek (AI ਵਿਸ਼ਲੇਸ਼ਣ ਅਤੇ ਏਮਬੇਡਿੰਗ); ਡੀਪਗ੍ਰਾਮ (ਮੀਟਿੰਗ ਟ੍ਰਾਂਸਕ੍ਰਿਪਸ਼ਨ) — ਸਵਾਲਾਂ ਨੂੰ ਜ਼ੀਰੋ-ਡੇਟਾ-ਰਿਟੈਂਸ਼ਨ API ਸਮਝੌਤਿਆਂ ਦੇ ਤਹਿਤ ਭੇਜਿਆ ਜਾਂਦਾ ਹੈ ਜਿੱਥੇ ਉਪਲਬਧ ਹੋਵੇ; (vi) ਈਮੇਲ ਡਿਲੀਵਰੀ — ਦੁਬਾਰਾ ਭੇਜੋ।';

  @override
  String get legalPrivacyTitle => 'ਪਰਾਈਵੇਟ ਨੀਤੀ';

  @override
  String get legalPrivacyTransfersBody =>
      'ਤੁਹਾਡੇ ਡੇਟਾ \'ਤੇ ਤੁਹਾਡੇ ਨਿਵਾਸ ਦੇ ਦੇਸ਼ ਤੋਂ ਬਾਹਰ ਪ੍ਰਕਿਰਿਆ ਕੀਤੀ ਜਾ ਸਕਦੀ ਹੈ। UK/EU ਤੋਂ ਟ੍ਰਾਂਸਫਰ ਲਈ, ਅਸੀਂ ਯੂਰਪੀਅਨ ਕਮਿਸ਼ਨ ਅਤੇ UK ICO ਦੁਆਰਾ ਪ੍ਰਵਾਨਿਤ ਮਿਆਰੀ ਇਕਰਾਰਨਾਮੇ ਦੀਆਂ ਧਾਰਾਵਾਂ (SCCs) \'ਤੇ ਭਰੋਸਾ ਕਰਦੇ ਹਾਂ। ਭਾਰਤ ਲਈ, ਟਰਾਂਸਫਰ ਅੰਤਰ-ਸਰਹੱਦ ਡਾਟਾ ਪ੍ਰਵਾਹ \'ਤੇ DPDP ਐਕਟ ਦੇ ਪ੍ਰਬੰਧਾਂ ਦੀ ਪਾਲਣਾ ਕਰਦੇ ਹਨ। ਕੀਨੀਆ ਲਈ, ਤਬਾਦਲੇ ਕੀਨੀਆ ਡੇਟਾ ਪ੍ਰੋਟੈਕਸ਼ਨ ਐਕਟ 2019 ਦੀ ਧਾਰਾ 48 ਦੀ ਪਾਲਣਾ ਕਰਦੇ ਹਨ। ਐਂਟਰਪ੍ਰਾਈਜ਼ ਕਿਰਾਏਦਾਰ ਗਵਰਨੈਂਸ ਸੈਟਿੰਗਾਂ ਰਾਹੀਂ ਡਾਟਾ ਰੈਜ਼ੀਡੈਂਸੀ ਪਾਬੰਦੀਆਂ ਦੀ ਬੇਨਤੀ ਕਰ ਸਕਦੇ ਹਨ।';

  @override
  String get legalPrivacyTransfersHeading => '10. ਅੰਤਰਰਾਸ਼ਟਰੀ ਟ੍ਰਾਂਸਫਰ';

  @override
  String get legalPrivacyUseBody =>
      'ਅਸੀਂ ਇਕੱਠੇ ਕੀਤੇ ਡੇਟਾ ਦੀ ਵਰਤੋਂ ਇਸ ਲਈ ਕਰਦੇ ਹਾਂ: (a) ਤੁਹਾਡਾ ਖਾਤਾ ਬਣਾਉਣਾ ਅਤੇ ਉਸ ਨੂੰ ਕਾਇਮ ਰੱਖਣਾ; (b) AI ਕਾਨੂੰਨੀ ਵਿਸ਼ਲੇਸ਼ਣ, ਮਾਮਲਾ ਪ੍ਰਬੰਧਨ, ਬਿਲਿੰਗ, ਖੋਜ, ਅਤੇ ਹੋਰ ਪਲੇਟਫਾਰਮ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਪ੍ਰਦਾਨ ਕਰੋ; (c) ਭੁਗਤਾਨ ਦੀ ਪ੍ਰਕਿਰਿਆ ਕਰੋ ਅਤੇ ਚਲਾਨ ਭੇਜੋ; (d) ਲੈਣ-ਦੇਣ ਸੰਬੰਧੀ ਈਮੇਲ ਭੇਜੋ (ਖਾਤੇ ਦੀ ਪੁਸ਼ਟੀ, ਪਾਸਵਰਡ ਰੀਸੈਟ, ਬਿਲਿੰਗ ਰਸੀਦਾਂ); (e) ਧੋਖਾਧੜੀ, ਸੁਰੱਖਿਆ ਘਟਨਾਵਾਂ, ਅਤੇ ਦੁਰਵਿਵਹਾਰ ਦਾ ਪਤਾ ਲਗਾਉਣਾ, ਜਾਂਚ ਕਰਨਾ ਅਤੇ ਰੋਕਣਾ; (f) ਅਦਾਲਤੀ ਹੁਕਮਾਂ ਅਤੇ ਰੈਗੂਲੇਟਰੀ ਲੋੜਾਂ ਸਮੇਤ ਕਾਨੂੰਨੀ ਜ਼ਿੰਮੇਵਾਰੀਆਂ ਦੀ ਪਾਲਣਾ; (g) ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਨੂੰ ਬਿਹਤਰ ਬਣਾਉਣ ਲਈ ਸਮੁੱਚੀ ਪਲੇਟਫਾਰਮ ਵਰਤੋਂ ਦਾ ਵਿਸ਼ਲੇਸ਼ਣ ਕਰੋ (ਸਿਰਫ਼ ਗੁਮਨਾਮ ਜਾਂ pseudonymized ਡੇਟਾ ਦੀ ਵਰਤੋਂ ਕਰਕੇ); (h) ਮਾਰਕੀਟਿੰਗ ਸੰਚਾਰ ਭੇਜੋ ਜਿੱਥੇ ਤੁਸੀਂ ਚੋਣ ਕੀਤੀ ਹੈ (ਤੁਸੀਂ ਕਿਸੇ ਵੀ ਸਮੇਂ ਸਹਿਮਤੀ ਵਾਪਸ ਲੈ ਸਕਦੇ ਹੋ)।';

  @override
  String get legalPrivacyUseHeading =>
      '4. ਅਸੀਂ ਤੁਹਾਡੀ ਜਾਣਕਾਰੀ ਦੀ ਵਰਤੋਂ ਕਿਵੇਂ ਕਰਦੇ ਹਾਂ';

  @override
  String get legalPublisherName => 'DVTech Ventures';

  @override
  String get legalStandardDisclaimer =>
      'ਛਤਰੀ ਕਾਨੂੰਨੀ ਜਾਣਕਾਰੀ, ਦਸਤਾਵੇਜ਼ ਸਪਸ਼ਟੀਕਰਨ, ਮੁੱਦੇ ਦੀ ਪਛਾਣ, ਅਤੇ ਜੋਖਮ ਵਿਸ਼ਲੇਸ਼ਣ ਪ੍ਰਦਾਨ ਕਰਦੀ ਹੈ। ਇਹ ਇੱਕ ਕਨੂੰਨੀ ਫਰਮ ਨਹੀਂ ਹੈ ਅਤੇ ਲਾਇਸੰਸਸ਼ੁਦਾ ਅਟਾਰਨੀ ਦੀ ਥਾਂ ਨਹੀਂ ਲੈਂਦੀ ਹੈ। ਤੁਹਾਡੀ ਸਥਿਤੀ ਲਈ ਵਿਸ਼ੇਸ਼ ਕਾਨੂੰਨੀ ਸਲਾਹ ਲਈ, ਆਪਣੇ ਅਧਿਕਾਰ ਖੇਤਰ ਵਿੱਚ ਕਿਸੇ ਯੋਗ ਵਕੀਲ ਨਾਲ ਸਲਾਹ ਕਰੋ।';

  @override
  String get legalTermsAIOutputsBody =>
      'AI ਆਉਟਪੁੱਟ ਵੱਡੇ ਭਾਸ਼ਾ ਮਾਡਲਾਂ ਦੁਆਰਾ ਤਿਆਰ ਕੀਤੇ ਜਾਂਦੇ ਹਨ ਅਤੇ ਸਿਰਫ ਜਾਣਕਾਰੀ ਦੇ ਉਦੇਸ਼ਾਂ ਲਈ ਪ੍ਰਦਾਨ ਕੀਤੇ ਜਾਂਦੇ ਹਨ। ਉਹ ਕਨੂੰਨੀ ਸਲਾਹ ਨਹੀਂ ਬਣਾਉਂਦੇ, ਇੱਕ ਅਟਾਰਨੀ-ਕਲਾਇੰਟ ਰਿਸ਼ਤਾ ਨਹੀਂ ਬਣਾਉਂਦੇ, ਅਤੇ ਕਿਸੇ ਯੋਗ ਵਕੀਲ ਦੀ ਸਲਾਹ ਦੇ ਬਦਲ ਵਜੋਂ ਉਹਨਾਂ \'ਤੇ ਭਰੋਸਾ ਨਹੀਂ ਕੀਤਾ ਜਾਣਾ ਚਾਹੀਦਾ ਹੈ। AI ਆਉਟਪੁੱਟ ਅਧੂਰੇ, ਗਲਤ, ਜਾਂ ਪੁਰਾਣੇ ਹੋ ਸਕਦੇ ਹਨ। ਕਾਨੂੰਨਾਂ ਅਤੇ ਕੇਸਾਂ ਦੇ ਹਵਾਲੇ ਸੁਤੰਤਰ ਤੌਰ \'ਤੇ ਪ੍ਰਮਾਣਿਤ ਕੀਤੇ ਜਾਣੇ ਚਾਹੀਦੇ ਹਨ। AI ਆਊਟਪੁੱਟ ਦੇ ਆਧਾਰ \'ਤੇ ਕੀਤੀ ਗਈ ਕਿਸੇ ਵੀ ਕਾਰਵਾਈ ਲਈ ਤੁਸੀਂ ਪੂਰੀ ਤਰ੍ਹਾਂ ਜ਼ਿੰਮੇਵਾਰ ਹੋ।';

  @override
  String get legalTermsAIOutputsHeading => '9. AI ਆਉਟਪੁੱਟ ਦੀ ਪ੍ਰਕਿਰਤੀ';

  @override
  String get legalTermsAccountBody =>
      'ਤੁਹਾਨੂੰ ਸਹੀ ਅਤੇ ਪੂਰੀ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਜਾਣਕਾਰੀ ਪ੍ਰਦਾਨ ਕਰਨੀ ਚਾਹੀਦੀ ਹੈ ਅਤੇ ਇਸਨੂੰ ਅੱਪਡੇਟ ਰੱਖਣਾ ਚਾਹੀਦਾ ਹੈ। ਤੁਸੀਂ ਆਪਣੇ ਪ੍ਰਮਾਣ ਪੱਤਰਾਂ ਦੀ ਗੁਪਤਤਾ ਅਤੇ ਤੁਹਾਡੇ ਖਾਤੇ ਦੇ ਅਧੀਨ ਸਾਰੀਆਂ ਗਤੀਵਿਧੀਆਂ ਲਈ ਜ਼ਿੰਮੇਵਾਰ ਹੋ। ਤੁਹਾਨੂੰ support@odaflow.com \'ਤੇ ਕਿਸੇ ਵੀ ਅਣਅਧਿਕਾਰਤ ਪਹੁੰਚ ਬਾਰੇ ਸਾਨੂੰ ਤੁਰੰਤ ਸੂਚਿਤ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ। ਅਸੀਂ ਉਹਨਾਂ ਖਾਤਿਆਂ ਨੂੰ ਅਯੋਗ ਕਰਨ ਦਾ ਅਧਿਕਾਰ ਰਾਖਵਾਂ ਰੱਖਦੇ ਹਾਂ ਜੋ ਇਹਨਾਂ ਸ਼ਰਤਾਂ ਦੀ ਉਲੰਘਣਾ ਕਰਦੇ ਹਨ ਜਾਂ ਸਾਨੂੰ ਵਾਜਬ ਤੌਰ \'ਤੇ ਸਮਝੌਤਾ ਕੀਤਾ ਗਿਆ ਹੈ।';

  @override
  String get legalTermsAccountHeading => '3. ਖਾਤਾ ਰਜਿਸਟਰੇਸ਼ਨ';

  @override
  String get legalTermsAgreementBody =>
      'ਇੱਕ ਖਾਤਾ ਬਣਾ ਕੇ ਜਾਂ ਕਿਸੇ ਵੀ ਛਤਰੀ ਸੇਵਾ ਦੀ ਵਰਤੋਂ ਕਰਕੇ, ਤੁਸੀਂ ਇਹਨਾਂ ਸ਼ਰਤਾਂ ਦੁਆਰਾ ਪਾਬੰਦ ਹੋਣ ਲਈ ਸਹਿਮਤ ਹੁੰਦੇ ਹੋ। ਜੇਕਰ ਤੁਸੀਂ ਕਿਸੇ ਕਨੂੰਨੀ ਫਰਮ, ਕੰਪਨੀ, ਜਾਂ ਹੋਰ ਕਾਨੂੰਨੀ ਹਸਤੀ ਦੀ ਤਰਫੋਂ ਪਲੇਟਫਾਰਮ ਦੀ ਵਰਤੋਂ ਕਰ ਰਹੇ ਹੋ, ਤਾਂ ਤੁਸੀਂ ਇਹ ਦਰਸਾਉਂਦੇ ਹੋ ਕਿ ਤੁਹਾਡੇ ਕੋਲ ਉਸ ਸੰਸਥਾ ਨੂੰ ਬੰਨ੍ਹਣ ਦਾ ਅਧਿਕਾਰ ਹੈ। ਜੇਕਰ ਤੁਸੀਂ ਇਹਨਾਂ ਸ਼ਰਤਾਂ ਨੂੰ ਸਵੀਕਾਰ ਨਹੀਂ ਕਰਦੇ ਹੋ, ਤਾਂ ਤੁਹਾਨੂੰ ਪਲੇਟਫਾਰਮ ਦੀ ਵਰਤੋਂ ਨਹੀਂ ਕਰਨੀ ਚਾਹੀਦੀ। ਉਪਭੋਗਤਾਵਾਂ ਦੀ ਉਮਰ ਘੱਟੋ-ਘੱਟ 18 ਸਾਲ ਹੋਣੀ ਚਾਹੀਦੀ ਹੈ।';

  @override
  String get legalTermsAgreementHeading => '1. ਸਵੀਕ੍ਰਿਤੀ';

  @override
  String get legalTermsChangesBody =>
      'ਅਸੀਂ ਸਮੇਂ-ਸਮੇਂ \'ਤੇ ਇਹਨਾਂ ਨਿਯਮਾਂ ਨੂੰ ਅਪਡੇਟ ਕਰ ਸਕਦੇ ਹਾਂ। ਸਮੱਗਰੀ ਤਬਦੀਲੀਆਂ ਨੂੰ ਲਾਗੂ ਹੋਣ ਤੋਂ ਘੱਟੋ-ਘੱਟ 30 ਦਿਨ ਪਹਿਲਾਂ ਈਮੇਲ ਅਤੇ ਇਨ-ਐਪ ਸੂਚਨਾ ਦੁਆਰਾ ਸੂਚਿਤ ਕੀਤਾ ਜਾਵੇਗਾ। ਪ੍ਰਭਾਵੀ ਮਿਤੀ ਤੋਂ ਬਾਅਦ ਨਿਰੰਤਰ ਵਰਤੋਂ ਸਵੀਕ੍ਰਿਤੀ ਬਣਦੀ ਹੈ।';

  @override
  String get legalTermsChangesHeading => '20. ਇਹਨਾਂ ਨਿਯਮਾਂ ਵਿੱਚ ਬਦਲਾਅ';

  @override
  String get legalTermsConfidentialityBody =>
      'ਅਸੀਂ ਤੁਹਾਡੀ ਸਮਗਰੀ ਅਤੇ ਮਾਮਲੇ ਦੇ ਡੇਟਾ ਨੂੰ ਗੁਪਤ ਮੰਨਦੇ ਹਾਂ ਅਤੇ ਸਾਡੀ ਗੋਪਨੀਯਤਾ ਨੀਤੀ ਜਾਂ ਕਾਨੂੰਨ ਦੁਆਰਾ ਲੋੜੀਂਦੇ ਅਨੁਸਾਰ ਇਸ ਨੂੰ ਛੱਡ ਕੇ ਤੀਜੀਆਂ ਧਿਰਾਂ ਨੂੰ ਇਸਦਾ ਖੁਲਾਸਾ ਨਹੀਂ ਕਰਾਂਗੇ। ਵਕੀਲ ਉਪਭੋਗਤਾਵਾਂ ਨੂੰ ਇਹ ਯਕੀਨੀ ਬਣਾਉਣਾ ਚਾਹੀਦਾ ਹੈ ਕਿ ਕਲਾਇੰਟ-ਗੁਪਤ ਸੰਚਾਰ ਲਾਗੂ ਪੇਸ਼ੇਵਰ ਵਿਸ਼ੇਸ਼ ਅਧਿਕਾਰ ਨਿਯਮਾਂ ਦੀ ਪਾਲਣਾ ਕਰਦੇ ਹਨ। ਸਾਡੇ ਸਿਸਟਮ ਕਿਰਾਏਦਾਰਾਂ ਦੇ ਡੇਟਾ ਨੂੰ ਅਲੱਗ-ਥਲੱਗ ਕਰਨ ਲਈ ਤਿਆਰ ਕੀਤੇ ਗਏ ਹਨ।';

  @override
  String get legalTermsConfidentialityHeading => '13. ਗੁਪਤਤਾ';

  @override
  String get legalTermsContactBody =>
      'ਇਹਨਾਂ ਨਿਯਮਾਂ ਬਾਰੇ ਸਵਾਲ: support@odaflow.com। DVTech ਵੈਂਚਰਸ, ਬੇਨਤੀ \'ਤੇ ਉਪਲਬਧ ਰਜਿਸਟਰਡ ਦਫਤਰ ਦੇ ਵੇਰਵੇ।';

  @override
  String get legalTermsContactHeading => '21. ਸੰਪਰਕ ਕਰੋ';

  @override
  String get legalTermsDataBody =>
      'ਸਾਡੇ ਨਿੱਜੀ ਡੇਟਾ ਦੇ ਸੰਗ੍ਰਹਿ ਅਤੇ ਵਰਤੋਂ ਦਾ ਵਰਣਨ ਗੋਪਨੀਯਤਾ ਨੀਤੀ ਵਿੱਚ ਕੀਤਾ ਗਿਆ ਹੈ। AI ਸਿਖਲਾਈ ਅਤੇ ਵਿਸ਼ਲੇਸ਼ਕ ਉਪਯੋਗਾਂ ਲਈ ਡੇਟਾ ਅਤੇ AI ਸਹਿਮਤੀ ਨੀਤੀ ਵਿੱਚ ਵਰਣਨ ਕੀਤੇ ਅਨੁਸਾਰ ਸਪਸ਼ਟ ਚੋਣ ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ।';

  @override
  String get legalTermsDataConsentLink => 'ਡਾਟਾ ਅਤੇ AI ਸਹਿਮਤੀ ਨੀਤੀ';

  @override
  String get legalTermsDataHeading => '15. ਡੇਟਾ ਅਤੇ ਗੋਪਨੀਯਤਾ';

  @override
  String get legalTermsDataPrivacyLink => 'ਪਰਾਈਵੇਟ ਨੀਤੀ';

  @override
  String get legalTermsDefinitionsBody =>
      '\"ਪਲੇਟਫਾਰਮ\" ਦਾ ਅਰਥ ਹੈ umbrella.okaylegal.ai ਅਤੇ ਸਾਰੀਆਂ ਸੰਬੰਧਿਤ ਐਪਲੀਕੇਸ਼ਨਾਂ, API, ਅਤੇ ਸੇਵਾਵਾਂ। \"ਖਪਤਕਾਰ ਉਪਭੋਗਤਾ\" ਦਾ ਅਰਥ ਹੈ ਇੱਕ ਕੁਦਰਤੀ ਵਿਅਕਤੀ ਜੋ ਪਲੇਟਫਾਰਮ ਦੀ ਵਰਤੋਂ ਕਰਕੇ ਆਪਣੀ ਕਾਨੂੰਨੀ ਸਥਿਤੀ ਨੂੰ ਸਮਝਣ ਲਈ। \"ਵਕੀਲ ਉਪਭੋਗਤਾ\" ਦਾ ਮਤਲਬ ਹੈ ਵਕੀਲ OS ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਹੋਏ ਲਾਇਸੰਸਸ਼ੁਦਾ ਕਾਨੂੰਨੀ ਪੇਸ਼ੇਵਰ। \"ਕਿਰਾਏਦਾਰ\" ਦਾ ਅਰਥ ਹੈ ਇੱਕ ਕਨੂੰਨੀ ਫਰਮ ਜਾਂ ਇੱਕ ਫਰਮ ਗਾਹਕੀ ਵਾਲੀ ਸੰਸਥਾ। \"AI ਆਉਟਪੁੱਟ\" ਦਾ ਅਰਥ ਹੈ Umbrella ਦੇ AI ਸਿਸਟਮਾਂ ਦੁਆਰਾ ਤਿਆਰ ਕੀਤਾ ਕੋਈ ਵੀ ਟੈਕਸਟ, ਵਿਸ਼ਲੇਸ਼ਣ, ਡਰਾਫਟ ਜਾਂ ਸਿਫ਼ਾਰਿਸ਼। \"ਮੈਟਰ\" ਦਾ ਮਤਲਬ ਹੈ ਵਕੀਲ OS ਦੁਆਰਾ ਪ੍ਰਬੰਧਿਤ ਕਾਨੂੰਨੀ ਕੇਸ ਜਾਂ ਲੈਣ-ਦੇਣ। \"DVTech Ventures\" ਜਾਂ \"we\" ਦਾ ਮਤਲਬ ਪਲੇਟਫਾਰਮ ਦਾ ਆਪਰੇਟਰ ਹੈ।';

  @override
  String get legalTermsDefinitionsHeading => '2. ਪਰਿਭਾਸ਼ਾਵਾਂ';

  @override
  String get legalTermsDescription =>
      'ਇਹ ਨਿਯਮ ਤੁਹਾਡੀ Umbrella ਦੀ ਵਰਤੋਂ ਨੂੰ ਨਿਯੰਤਰਿਤ ਕਰਦੇ ਹਨ — DVTech Ventures ਦੁਆਰਾ ਸੰਚਾਲਿਤ AI-ਦੇਸੀ ਕਨੂੰਨੀ ਪਲੇਟਫਾਰਮ। ਪਲੇਟਫਾਰਮ ਦੇ ਕਿਸੇ ਵੀ ਹਿੱਸੇ ਦੀ ਵਰਤੋਂ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਕਿਰਪਾ ਕਰਕੇ ਉਹਨਾਂ ਨੂੰ ਧਿਆਨ ਨਾਲ ਪੜ੍ਹੋ।';

  @override
  String get legalTermsDisputeBody =>
      'ਭਾਰਤੀ ਉਪਭੋਗਤਾ: ਇਹ ਸ਼ਰਤਾਂ ਭਾਰਤ ਦੇ ਕਾਨੂੰਨਾਂ ਦੁਆਰਾ ਨਿਯੰਤਰਿਤ ਹਨ; ਬੰਗਲੌਰ ਵਿੱਚ ਬੈਠੇ ਸਾਲਸੀ ਅਤੇ ਸੁਲ੍ਹਾ ਐਕਟ 1996 ਦੇ ਤਹਿਤ ਬਾਇੰਡਿੰਗ ਆਰਬਿਟਰੇਸ਼ਨ ਦੁਆਰਾ ਵਿਵਾਦਾਂ ਦਾ ਹੱਲ ਕੀਤਾ ਜਾਵੇਗਾ। ਸੰਯੁਕਤ ਰਾਜ ਦੇ ਉਪਭੋਗਤਾ: ਵਿਵਾਦਾਂ ਨੂੰ ਡੇਲਾਵੇਅਰ ਵਿੱਚ ਬੈਠੇ AAA ਵਪਾਰਕ ਸਾਲਸੀ ਨਿਯਮਾਂ ਦੇ ਅਧੀਨ ਬਾਇੰਡਿੰਗ ਆਰਬਿਟਰੇਸ਼ਨ ਦੁਆਰਾ ਹੱਲ ਕੀਤਾ ਜਾਵੇਗਾ; ਕਲਾਸ ਐਕਸ਼ਨ ਛੋਟ ਲਾਗੂ ਹੁੰਦੀ ਹੈ। ਕੀਨੀਆ ਉਪਭੋਗਤਾ: ਇਹ ਸ਼ਰਤਾਂ ਕੀਨੀਆ ਦੇ ਕਾਨੂੰਨਾਂ ਦੁਆਰਾ ਨਿਯੰਤਰਿਤ ਹਨ; ਵਿਵਾਦਾਂ ਦਾ ਹੱਲ ਨੈਰੋਬੀ ਸੈਂਟਰ ਫਾਰ ਇੰਟਰਨੈਸ਼ਨਲ ਆਰਬਿਟਰੇਸ਼ਨ (NCIA) ਨਿਯਮਾਂ ਅਧੀਨ ਕੀਤਾ ਜਾਵੇਗਾ। ਯੂਨਾਈਟਿਡ ਕਿੰਗਡਮ ਉਪਭੋਗਤਾ: ਇਹ ਸ਼ਰਤਾਂ ਅੰਗਰੇਜ਼ੀ ਕਾਨੂੰਨ ਦੁਆਰਾ ਨਿਯੰਤਰਿਤ ਹਨ; ਵਿਵਾਦ ਇੰਗਲੈਂਡ ਅਤੇ ਵੇਲਜ਼ ਦੀਆਂ ਅਦਾਲਤਾਂ ਦੇ ਨਿਵੇਕਲੇ ਅਧਿਕਾਰ ਖੇਤਰ ਵਿੱਚ ਜਮ੍ਹਾਂ ਕੀਤੇ ਜਾਣਗੇ। ਸਾਰੇ ਮਾਮਲਿਆਂ ਵਿੱਚ, ਤੁਹਾਨੂੰ ਸਮਰੱਥ ਅਦਾਲਤ ਤੋਂ ਤੁਰੰਤ ਹੁਕਮਨਾਮਾ ਰਾਹਤ ਦੀ ਮੰਗ ਕਰਨ ਤੋਂ ਕੁਝ ਵੀ ਨਹੀਂ ਰੋਕਦਾ।';

  @override
  String get legalTermsDisputeHeading => '18. ਵਿਵਾਦ ਨਿਪਟਾਰਾ ਅਤੇ ਸੰਚਾਲਨ ਕਾਨੂੰਨ';

  @override
  String get legalTermsIPContentBody =>
      'ਤੁਸੀਂ ਪਲੇਟਫਾਰਮ \'ਤੇ ਜਮ੍ਹਾਂ ਕੀਤੀ ਸਾਰੀ ਸਮੱਗਰੀ ਦੀ ਮਲਕੀਅਤ ਬਰਕਰਾਰ ਰੱਖਦੇ ਹੋ। ਸਮੱਗਰੀ ਸਪੁਰਦ ਕਰਕੇ ਤੁਸੀਂ DVTech Ventures ਨੂੰ ਪੂਰੀ ਤਰ੍ਹਾਂ ਸੇਵਾਵਾਂ ਪ੍ਰਦਾਨ ਕਰਨ ਲਈ ਤੁਹਾਡੀ ਸਮੱਗਰੀ ਦੀ ਪ੍ਰਕਿਰਿਆ, ਸਟੋਰ ਕਰਨ ਅਤੇ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰਨ ਲਈ ਇੱਕ ਵਿਸ਼ਵਵਿਆਪੀ, ਰਾਇਲਟੀ-ਮੁਕਤ, ਗੈਰ-ਨਿਵੇਕਲਾ ਲਾਇਸੈਂਸ ਦਿੰਦੇ ਹੋ। ਇਹ ਲਾਇਸੰਸ AI ਸਿਖਲਾਈ ਤੱਕ ਨਹੀਂ ਵਧਾਇਆ ਜਾਂਦਾ ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਡੇਟਾ ਅਤੇ AI ਸਹਿਮਤੀ ਨੀਤੀ ਦੇ ਅਧੀਨ ਚੋਣ ਨਹੀਂ ਕਰਦੇ।';

  @override
  String get legalTermsIPHeading => '12. ਬੌਧਿਕ ਸੰਪਤੀ';

  @override
  String get legalTermsIPPlatformBody =>
      'DVTech Ventures ਕੋਲ ਅੰਬਰੇਲਾ ਪਲੇਟਫਾਰਮ, ਬ੍ਰਾਂਡ, ਅੰਡਰਲਾਈੰਗ AI ਮਾਡਲਾਂ, ਅਤੇ ਤਕਨਾਲੋਜੀ ਦੇ ਸਾਰੇ ਅਧਿਕਾਰ ਹਨ। ਤੁਹਾਨੂੰ ਤੁਹਾਡੀ ਗਾਹਕੀ ਦੀ ਮਿਆਦ ਲਈ ਪਲੇਟਫਾਰਮ ਦੀ ਵਰਤੋਂ ਕਰਨ ਲਈ ਇੱਕ ਸੀਮਤ, ਗੈਰ-ਨਿਵੇਕਲਾ, ਗੈਰ-ਤਬਾਦਲਾਯੋਗ ਲਾਇਸੈਂਸ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ।';

  @override
  String get legalTermsIndemnityBody =>
      'ਤੁਸੀਂ ਨੁਕਸਾਨ ਰਹਿਤ DVTech ਵੈਂਚਰਸ ਅਤੇ ਇਸਦੇ ਅਧਿਕਾਰੀਆਂ, ਨਿਰਦੇਸ਼ਕਾਂ, ਕਰਮਚਾਰੀਆਂ, ਅਤੇ ਏਜੰਟਾਂ ਨੂੰ ਕਿਸੇ ਵੀ ਦਾਅਵਿਆਂ, ਨੁਕਸਾਨਾਂ, ਨੁਕਸਾਨਾਂ ਅਤੇ ਖਰਚਿਆਂ (ਵਾਜਬ ਕਨੂੰਨੀ ਫੀਸਾਂ ਸਮੇਤ) ਤੋਂ ਅਤੇ ਇਸਦੇ ਵਿਰੁੱਧ ਮੁਆਵਜ਼ਾ ਦੇਣ, ਬਚਾਅ ਕਰਨ ਅਤੇ ਰੱਖਣ ਲਈ ਸਹਿਮਤ ਹੋ: (a) ਇਹਨਾਂ ਨਿਯਮਾਂ ਦੀ ਉਲੰਘਣਾ ਵਿੱਚ ਪਲੇਟਫਾਰਮ ਦੀ ਤੁਹਾਡੀ ਵਰਤੋਂ; (ਬੀ) ਕਿਸੇ ਲਾਗੂ ਕਾਨੂੰਨ ਦੀ ਤੁਹਾਡੀ ਉਲੰਘਣਾ; (c) ਤੁਹਾਡੇ ਦੁਆਰਾ ਜਮ੍ਹਾਂ ਕੀਤੀ ਸਮੱਗਰੀ ਜੋ ਕਿਸੇ ਤੀਜੀ ਧਿਰ ਦੇ ਅਧਿਕਾਰਾਂ ਦੀ ਉਲੰਘਣਾ ਕਰਦੀ ਹੈ; (d) ਕਨੂੰਨੀ ਸਲਾਹ ਜਾਂ ਸੇਵਾਵਾਂ ਜੋ ਤੁਸੀਂ ਪਲੇਟਫਾਰਮ ਦੀ ਵਰਤੋਂ ਕਰਕੇ ਆਪਣੇ ਗਾਹਕਾਂ ਨੂੰ ਪ੍ਰਦਾਨ ਕਰਦੇ ਹੋ।';

  @override
  String get legalTermsIndemnityHeading => '17. ਮੁਆਵਜ਼ਾ';

  @override
  String get legalTermsLawyerUsersBody =>
      'ਵਕੀਲ ਉਪਭੋਗਤਾ ਸੁਤੰਤਰ ਲਾਇਸੰਸਸ਼ੁਦਾ ਪੇਸ਼ੇਵਰ ਹੁੰਦੇ ਹਨ। ਵਕੀਲ OS ਦੀ ਵਰਤੋਂ ਕਰਕੇ, ਤੁਸੀਂ ਪੁਸ਼ਟੀ ਕਰਦੇ ਹੋ ਕਿ ਤੁਸੀਂ ਆਪਣੇ ਅਧਿਕਾਰ ਖੇਤਰ ਵਿੱਚ ਇੱਕ ਵੈਧ ਅਭਿਆਸ ਸਰਟੀਫਿਕੇਟ ਰੱਖਦੇ ਹੋ ਅਤੇ ਇਹ ਕਿ ਤੁਸੀਂ ਪਲੇਟਫਾਰਮ ਦੀ ਵਰਤੋਂ ਲਾਗੂ ਪੇਸ਼ੇਵਰ ਆਚਰਣ ਨਿਯਮਾਂ ਅਤੇ ਬਾਰ ਨਿਯਮਾਂ ਦੀ ਪਾਲਣਾ ਵਿੱਚ ਕਰੋਗੇ। ਤੁਸੀਂ ਆਪਣੇ ਗਾਹਕਾਂ ਨੂੰ ਪ੍ਰਦਾਨ ਕੀਤੇ ਗਏ ਸਾਰੇ ਕਾਨੂੰਨੀ ਕੰਮ ਅਤੇ ਸਲਾਹ ਦੀ ਗੁਣਵੱਤਾ ਅਤੇ ਕਾਨੂੰਨੀਤਾ ਲਈ ਪੂਰੀ ਤਰ੍ਹਾਂ ਜ਼ਿੰਮੇਵਾਰ ਰਹਿੰਦੇ ਹੋ। ਛਤਰੀ ਟੂਲ ਪ੍ਰਦਾਨ ਕਰਦੀ ਹੈ - ਇਹ ਵਕੀਲ ਉਪਭੋਗਤਾਵਾਂ ਦੇ ਪੇਸ਼ੇਵਰ ਆਚਰਣ ਦੀ ਨਿਗਰਾਨੀ ਜਾਂ ਗਾਰੰਟੀ ਨਹੀਂ ਦਿੰਦੀ।';

  @override
  String get legalTermsLawyerUsersHeading => '11. ਵਕੀਲ ਉਪਭੋਗਤਾ';

  @override
  String get legalTermsLiabilityBody =>
      'ਲਾਗੂ ਕਨੂੰਨ ਦੁਆਰਾ ਆਗਿਆ ਦਿੱਤੀ ਅਧਿਕਤਮ ਹੱਦ ਤੱਕ: (a) ਇਹਨਾਂ ਸ਼ਰਤਾਂ ਤੋਂ ਪੈਦਾ ਹੋਣ ਵਾਲੇ ਜਾਂ ਇਹਨਾਂ ਨਾਲ ਸੰਬੰਧਿਤ ਕਿਸੇ ਵੀ ਦਾਅਵੇ ਲਈ DVTECH ਉੱਦਮਾਂ ਦੀ ਸਮੁੱਚੀ ਦੇਣਦਾਰੀ ਜਾਂ ਪਲੇਟਫਾਰਮ ਤੁਹਾਡੇ ਲਈ US12 ਤੱਕ ਸੀਮਿਤ ਹੈ ਦਾਅਵੇ ਤੋਂ ਪਹਿਲਾਂ ਦੇ ਮਹੀਨੇ; (ਬੀ) ਅਸੀਂ ਅਸਿੱਧੇ, ਇਤਫਾਕ, ਵਿਸ਼ੇਸ਼, ਪਰਿਣਾਮੀ, ਜਾਂ ਦੰਡਕਾਰੀ ਨੁਕਸਾਨ, ਲਾਭ ਦੇ ਨੁਕਸਾਨ, ਡੇਟਾ ਦੇ ਨੁਕਸਾਨ, ਜਾਂ ਸਦਭਾਵਨਾ ਦੇ ਨੁਕਸਾਨ ਲਈ ਜ਼ਿੰਮੇਵਾਰ ਨਹੀਂ ਹਾਂ। ਇਹ ਸੀਮਾਵਾਂ ਲਾਗੂ ਹੁੰਦੀਆਂ ਹਨ ਭਾਵੇਂ ਸਾਨੂੰ ਅਜਿਹੇ ਨੁਕਸਾਨਾਂ ਦੀ ਸੰਭਾਵਨਾ ਬਾਰੇ ਸਲਾਹ ਦਿੱਤੀ ਗਈ ਹੋਵੇ ਅਤੇ ਕਾਨੂੰਨੀ ਸਿਧਾਂਤ ਦੀ ਪਰਵਾਹ ਕੀਤੇ ਬਿਨਾਂ।';

  @override
  String get legalTermsLiabilityHeading => '16. ਦੇਣਦਾਰੀ ਦੀ ਸੀਮਾ';

  @override
  String get legalTermsNotLawFirmBody =>
      'ਛਤਰੀ ਇੱਕ ਟੈਕਨਾਲੋਜੀ ਪਲੇਟਫਾਰਮ ਹੈ, ਇੱਕ ਲਾਅ ਫਰਮ ਨਹੀਂ। DVTech Ventures ਕਾਨੂੰਨੀ ਸਲਾਹ ਜਾਂ ਕਾਨੂੰਨੀ ਪ੍ਰਤੀਨਿਧਤਾ ਪ੍ਰਦਾਨ ਨਹੀਂ ਕਰਦਾ ਹੈ। ਪਲੇਟਫਾਰਮ ਦੀ ਵਰਤੋਂ ਤੁਹਾਡੇ ਅਤੇ DVTech ਵੈਂਚਰਸ ਵਿਚਕਾਰ ਅਟਾਰਨੀ-ਕਲਾਇੰਟ ਰਿਸ਼ਤਾ ਨਹੀਂ ਬਣਾਉਂਦੀ ਹੈ। ਵਕੀਲ ਬਾਜ਼ਾਰ ਤੁਹਾਨੂੰ ਸੁਤੰਤਰ ਲਾਇਸੰਸਸ਼ੁਦਾ ਵਕੀਲਾਂ ਨਾਲ ਜੋੜਦਾ ਹੈ; ਮਾਰਕਿਟਪਲੇਸ ਵਕੀਲ ਨਾਲ ਕੋਈ ਵੀ ਸ਼ਮੂਲੀਅਤ ਤੁਹਾਡੇ ਅਤੇ ਉਸ ਵਕੀਲ ਦੇ ਵਿਚਕਾਰ ਇੱਕ ਵੱਖਰੇ ਰਿਟੇਨਰ ਸਮਝੌਤੇ ਦੁਆਰਾ ਨਿਯੰਤਰਿਤ ਕੀਤੀ ਜਾਂਦੀ ਹੈ।';

  @override
  String get legalTermsNotLawFirmHeading => '10. ਕੋਈ ਕਨੂੰਨੀ ਫਰਮ ਨਹੀਂ';

  @override
  String get legalTermsOfService => 'ਸੇਵਾ ਦੀਆਂ ਸ਼ਰਤਾਂ';

  @override
  String get legalTermsPermittedUseBody =>
      'ਤੁਸੀਂ ਪਲੇਟਫਾਰਮ ਦੀ ਵਰਤੋਂ ਇਸ ਲਈ ਕਰ ਸਕਦੇ ਹੋ: ਨਿੱਜੀ ਜਾਂ ਪੇਸ਼ੇਵਰ ਵਰਤੋਂ ਲਈ AI ਦੁਆਰਾ ਤਿਆਰ ਕਾਨੂੰਨੀ ਜਾਣਕਾਰੀ ਪ੍ਰਾਪਤ ਕਰੋ; ਕਾਨੂੰਨੀ ਮਾਮਲਿਆਂ, ਗਾਹਕਾਂ, ਬਿਲਿੰਗ, ਅਤੇ ਦਸਤਾਵੇਜ਼ਾਂ ਦਾ ਪ੍ਰਬੰਧਨ ਕਰੋ (ਵਕੀਲ OS); ਲਾਇਸੰਸਸ਼ੁਦਾ ਅਟਾਰਨੀ ਨਾਲ ਜੁੜਨ ਲਈ ਵਕੀਲ ਬਾਜ਼ਾਰ ਤੱਕ ਪਹੁੰਚ ਕਰੋ; ਅਤੇ ਸਾਡੇ ਦਸਤਾਵੇਜ਼ੀ API ਦੁਆਰਾ ਪਲੇਟਫਾਰਮ ਨੂੰ ਆਪਣੇ ਸਿਸਟਮਾਂ ਨਾਲ ਏਕੀਕ੍ਰਿਤ ਕਰੋ।';

  @override
  String get legalTermsPermittedUseHeading => '4. ਵਰਤੋਂ ਦੀ ਇਜਾਜ਼ਤ ਹੈ';

  @override
  String get legalTermsProhibitedUseBody =>
      'ਤੁਹਾਨੂੰ ਇਹ ਨਹੀਂ ਕਰਨਾ ਚਾਹੀਦਾ: (ਏ) ਕਿਸੇ ਵਕੀਲ, ਜੱਜ, ਜਾਂ ਸਰਕਾਰੀ ਅਧਿਕਾਰੀ ਦਾ ਰੂਪ ਧਾਰਣਾ; (b) ਵਕੀਲ ਦੀ ਸਮੀਖਿਆ ਤੋਂ ਬਿਨਾਂ ਤੀਜੀ ਧਿਰਾਂ ਨੂੰ ਰਸਮੀ ਕਾਨੂੰਨੀ ਸਲਾਹ ਵਜੋਂ AI ਆਊਟਪੁੱਟ ਦੀ ਵਰਤੋਂ ਕਰੋ; (c) ਗੈਰ-ਕਾਨੂੰਨੀ, ਅਪਮਾਨਜਨਕ, ਜਾਂ ਧੋਖਾਧੜੀ ਵਾਲੀ ਸਮੱਗਰੀ ਜਮ੍ਹਾਂ ਕਰੋ; (d) ਅੰਡਰਲਾਈੰਗ ਏਆਈ ਮਾਡਲਾਂ ਜਾਂ ਸਿਖਲਾਈ ਡੇਟਾ ਨੂੰ ਉਲਟਾ-ਇੰਜੀਨੀਅਰ, ਸਕ੍ਰੈਪ, ਜਾਂ ਐਕਸਟਰੈਕਟ ਕਰਨ ਦੀ ਕੋਸ਼ਿਸ਼; (e) ਲਿਖਤੀ ਸਹਿਮਤੀ ਤੋਂ ਬਿਨਾਂ ਪਲੇਟਫਾਰਮ ਤੱਕ ਦੁਬਾਰਾ ਵੇਚਣਾ ਜਾਂ ਉਪ-ਲਾਇਸੈਂਸ ਪਹੁੰਚ; (f) ਪਲੇਟਫਾਰਮ ਦੀ ਵਰਤੋਂ ਕਿਸੇ ਵੀ ਤਰੀਕੇ ਨਾਲ ਕਰੋ ਜੋ ਲਾਗੂ ਕਾਨੂੰਨ ਦੀ ਉਲੰਘਣਾ ਕਰਦਾ ਹੈ, ਜਿਸ ਵਿੱਚ ਡੇਟਾ ਸੁਰੱਖਿਆ, ਖਪਤਕਾਰ ਸੁਰੱਖਿਆ, ਅਤੇ ਕਾਨੂੰਨੀ ਪੇਸ਼ੇ ਦੇ ਨਿਯਮਾਂ ਸ਼ਾਮਲ ਹਨ; (g) ਤੀਜੀ-ਧਿਰ ਦੇ ਬੌਧਿਕ ਸੰਪੱਤੀ ਅਧਿਕਾਰਾਂ ਦੀ ਉਲੰਘਣਾ ਕਰਨ ਵਾਲੀ ਸਮੱਗਰੀ ਦਰਜ ਕਰੋ।';

  @override
  String get legalTermsProhibitedUseHeading => '5. ਵਰਜਿਤ ਵਰਤੋਂ';

  @override
  String get legalTermsRefundBody =>
      'ਤੁਸੀਂ ਕਿਸੇ ਵੀ ਸਮੇਂ ਖਾਤਾ ਸੈਟਿੰਗਾਂ ਤੋਂ ਆਪਣੀ ਗਾਹਕੀ ਨੂੰ ਰੱਦ ਕਰ ਸਕਦੇ ਹੋ। ਰੱਦ ਕਰਨਾ ਮੌਜੂਦਾ ਬਿਲਿੰਗ ਮਿਆਦ ਦੇ ਅੰਤ \'ਤੇ ਲਾਗੂ ਹੁੰਦਾ ਹੈ; ਅਣਵਰਤੇ ਸਮੇਂ ਲਈ ਕੋਈ ਅੰਸ਼ਕ ਰਿਫੰਡ ਜਾਰੀ ਨਹੀਂ ਕੀਤਾ ਜਾਂਦਾ ਹੈ। ਜੇਕਰ ਤੁਹਾਨੂੰ ਲੱਗਦਾ ਹੈ ਕਿ ਤੁਹਾਡੇ ਤੋਂ ਗਲਤੀ ਨਾਲ ਚਾਰਜ ਲਗਾਇਆ ਗਿਆ ਹੈ, ਤਾਂ ਚਾਰਜ ਦੇ 30 ਦਿਨਾਂ ਦੇ ਅੰਦਰ support@odaflow.com \'ਤੇ ਸੰਪਰਕ ਕਰੋ। ਅਸੀਂ ਸਮੀਖਿਆ ਕਰਾਂਗੇ ਅਤੇ, ਜੇਕਰ ਉਚਿਤ ਹੋਵੇ, ਤਾਂ ਸਾਡੇ ਵਿਵੇਕ \'ਤੇ ਪ੍ਰੋ-ਰੇਟਾ ਰਿਫੰਡ ਜਾਰੀ ਕਰਾਂਗੇ।';

  @override
  String get legalTermsRefundHeading => '8. ਰਿਫੰਡ ਅਤੇ ਰੱਦ ਕਰਨਾ';

  @override
  String get legalTermsSeverabilityBody =>
      'ਜੇਕਰ ਇਹਨਾਂ ਸ਼ਰਤਾਂ ਦਾ ਕੋਈ ਵੀ ਪ੍ਰਬੰਧ ਲਾਗੂ ਕਰਨਯੋਗ ਨਹੀਂ ਪਾਇਆ ਜਾਂਦਾ ਹੈ, ਤਾਂ ਬਾਕੀ ਪ੍ਰਬੰਧ ਪੂਰੀ ਤਰ੍ਹਾਂ ਨਾਲ ਜਾਰੀ ਰਹਿੰਦੇ ਹਨ। ਕਿਸੇ ਵੀ ਅਧਿਕਾਰ ਨੂੰ ਲਾਗੂ ਕਰਨ ਵਿੱਚ ਸਾਡੀ ਅਸਫਲਤਾ ਉਸ ਅਧਿਕਾਰ ਦੀ ਛੋਟ ਨਹੀਂ ਹੈ। ਇਹ ਸ਼ਰਤਾਂ, ਗੋਪਨੀਯਤਾ ਨੀਤੀ ਅਤੇ ਡੇਟਾ ਅਤੇ AI ਸਹਿਮਤੀ ਨੀਤੀ ਦੇ ਨਾਲ, ਪਲੇਟਫਾਰਮ ਦੇ ਸੰਬੰਧ ਵਿੱਚ ਤੁਹਾਡੇ ਅਤੇ DVTech ਵੈਂਚਰਸ ਵਿਚਕਾਰ ਪੂਰੇ ਸਮਝੌਤੇ ਦਾ ਗਠਨ ਕਰਦੀਆਂ ਹਨ।';

  @override
  String get legalTermsSeverabilityHeading => '19. ਜਨਰਲ';

  @override
  String get legalTermsSubscriptionBody =>
      'ਅਦਾਇਗੀ ਯੋਜਨਾਵਾਂ ਦਾ ਮਹੀਨਾਵਾਰ ਜਾਂ ਸਾਲਾਨਾ ਚੱਕਰ \'ਤੇ ਪਹਿਲਾਂ ਤੋਂ ਬਿਲ ਕੀਤਾ ਜਾਂਦਾ ਹੈ। ਚੈੱਕਆਉਟ ਵੇਲੇ ਕੀਮਤਾਂ ਤੁਹਾਡੀ ਸਥਾਨਕ ਮੁਦਰਾ ਵਿੱਚ ਪ੍ਰਦਰਸ਼ਿਤ ਹੁੰਦੀਆਂ ਹਨ ਅਤੇ ਲਾਗੂ ਟੈਕਸ ਸ਼ਾਮਲ ਹੋ ਸਕਦੀਆਂ ਹਨ। ਗਾਹਕੀ ਹਰੇਕ ਬਿਲਿੰਗ ਮਿਆਦ ਦੇ ਅੰਤ \'ਤੇ ਆਟੋ-ਰੀਨਿਊ ਹੋ ਜਾਂਦੀ ਹੈ ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਨਵਿਆਉਣ ਦੀ ਮਿਤੀ ਤੋਂ ਪਹਿਲਾਂ ਰੱਦ ਨਹੀਂ ਕਰਦੇ। ਭੁਗਤਾਨ ਕਰਨ ਵਿੱਚ ਅਸਫਲ ਰਹਿਣ ਦੇ ਨਤੀਜੇ ਵਜੋਂ ਪਹੁੰਚ ਨੂੰ ਮੁਅੱਤਲ ਜਾਂ ਸਮਾਪਤ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ।';

  @override
  String get legalTermsSubscriptionHeading => '6. ਗਾਹਕੀਆਂ ਅਤੇ ਬਿਲਿੰਗ';

  @override
  String get legalTermsTitle => 'ਸੇਵਾ ਦੀਆਂ ਸ਼ਰਤਾਂ';

  @override
  String get legalTermsTrialBody =>
